    fn aim_real_player_fireball_at_bee_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        bee: crate::native_world::BeeCreatureRuntime,
    ) {
        let (player_slot, player_fov, direction_bits) = {
            let compatibility = session.backend().campaign.level2_compatibility();
            (
                compatibility.state.entity_index,
                compatibility.state.entity_fov,
                compatibility.shared_spells().player_entity().control_flags & 0x0300,
            )
        };
        let mut predicted_target = bee.position;
        crate::move_entity(&mut predicted_target, bee.yaw, 0, bee.actual_speed);
        predicted_target.z = predicted_target
            .z
            .wrapping_sub(crate::level1_mission::FIREBALL_COLLISION_VERTICAL_OFFSET);
        let mut launch_position = predicted_target;
        crate::move_entity(
            &mut launch_position,
            bee.yaw.wrapping_add(1024),
            0,
            crate::level1_mission::FIREBALL_SPEED,
        );
        launch_position.z = crate::FlightWorld::ground_height(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .canonical_terrain(),
            launch_position,
        )
        .wrapping_add(256)
        .wrapping_add(player_fov);
        let (yaw, pitch) =
            crate::level1_mission::projectile_guidance_angles(launch_position, predicted_target);
        let hand_yaw = if direction_bits & 0x0100 != 0 {
            Some(yaw.wrapping_sub(512))
        } else if direction_bits & 0x0200 != 0 {
            Some(yaw.wrapping_add(512))
        } else {
            None
        };
        let mut player_position = crate::Position {
            z: launch_position.z.wrapping_sub(player_fov),
            ..launch_position
        };
        if let Some(hand_yaw) = hand_yaw {
            crate::move_entity(&mut player_position, hand_yaw.wrapping_add(1024), 0, 256);
        }
        let compatibility = session.backend_mut().campaign.level2_compatibility_mut();
        compatibility
            .set_level2_entity_position(player_slot, player_position)
            .expect("Bee Fireball boundary remains map-linked");
        compatibility.set_level2_player_aim_for_test(yaw, pitch);
    }

    fn drive_real_bee_to_fireball_action_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        authored_index: u16,
    ) -> crate::native_world::BeeCreatureRuntime {
        for _ in 0..160 {
            let bee = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .find(|bee| bee.authored_index() == Some(authored_index))
                .copied()
                .expect("production Bee remains before its public Fireball callback");
            if bee.action == 17 && bee.active && bee.drawing_enabled && bee.life >= 0 {
                return bee;
            }
            assert!(
                !matches!(bee.action, 20 | 21),
                "Bee {authored_index} reached death before the selected Fireball"
            );
            let player_position = if bee.action == 23 {
                let mut position = bee.position;
                crate::move_entity(&mut position, bee.yaw, 0, 1_000);
                position.z = bee.position.z;
                position
            } else {
                crate::Position {
                    x: bee.position.x.wrapping_add(20_000),
                    y: bee.position.y.wrapping_add(20_000),
                    z: bee.position.z,
                }
            };
            position_player_at_bee_fireball_boundary_for_test(session, player_position);
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let bee = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .bee_creatures()
            .iter()
            .find(|bee| bee.authored_index() == Some(authored_index))
            .copied();
        panic!("Bee {authored_index} did not return to source action 17: {bee:?}");
    }

    fn fire_real_player_fireball_at_bee_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        authored_index: u16,
    ) -> crate::native_world::BeeCreatureRuntime {
        let bee = drive_real_bee_to_fireball_action_for_test(session, authored_index);
        let life_before = bee.life;
        aim_real_player_fireball_at_bee_for_test(session, bee);
        session
            .step(
                guard(session),
                GameCommand {
                    select_spell: Some(SemanticId::parse("spell.fireball").unwrap()),
                    cast_selected: true,
                    ..GameCommand::default()
                },
            )
            .unwrap();
        for _ in 0..=24 {
            let compatibility = session.backend().campaign.level2_compatibility();
            let current = compatibility
                .economy()
                .bee_creatures()
                .iter()
                .find(|bee| bee.authored_index() == Some(authored_index))
                .copied()
                .expect("the public Fireball leaves its real Bee addressable");
            if current.life == life_before.wrapping_sub(250)
                && current.damage_attacker_entity_index == compatibility.state.entity_index
            {
                assert!(matches!(current.action, 18 | 20));
                return current;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        panic!(
            "one ordinary semantic Fireball did not reach Bee {authored_index}'s source mailbox"
        );
    }

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    struct BeeFireballDamageReceipt {
        authored_index: u16,
        source_slot: u16,
        generation: u32,
        life_before: i16,
        life_after: i16,
    }

    fn real_level_two_new_event_replaceable_slots_for_test(
        economy: &crate::native_world::Level2EconomyState,
    ) -> BTreeSet<u16> {
        const SOURCE_REPLACEABLE_FLAG: u32 = 0x0002_0000;

        let mut slots = BTreeSet::new();
        macro_rules! collect_flagged {
            ($rows:expr) => {
                slots.extend(
                    $rows
                        .iter()
                        .filter(|row| {
                            row.active && row.control_flags & SOURCE_REPLACEABLE_FLAG != 0
                        })
                        .map(|row| row.source_entity_index),
                );
            };
        }
        collect_flagged!(economy.spheres());
        collect_flagged!(economy.death_bursts());
        collect_flagged!(economy.authored_model1());
        collect_flagged!(economy.model59_smoke_children());
        collect_flagged!(economy.authored_model5_water_splashes());
        collect_flagged!(economy.authored_model13());
        collect_flagged!(economy.authored_model6());
        collect_flagged!(economy.model13_spawned_children());
        collect_flagged!(economy.model17_spawned_children());
        collect_flagged!(economy.model76_tail_spawns());
        slots.extend(
            economy
                .castle_children()
                .iter()
                .filter(|child| {
                    child.active
                        && child.source_class == 5
                        && child.model == 15
                        && child.control_flags & SOURCE_REPLACEABLE_FLAG != 0
                })
                .map(|child| child.source_entity_index),
        );
        slots
    }

    fn fire_real_player_fireball_at_bee_swarm_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        requested_authored_index: u16,
        exact_package_rows: &[u16],
    ) -> Vec<BeeFireballDamageReceipt> {
        // A class-10/model-0 impact remains in the source arena for its
        // authored eight-life callback tail.  Do not pile another cast onto
        // an occupied projectile/effect arena: ordinary no-input turns own
        // its expiry, following-pass reclaim, and player mana recharge.
        for _ in 0..=24 {
            let compatibility = session.backend().campaign.level2_compatibility();
            let economy = compatibility.economy();
            let player_slot = compatibility.state.entity_index;
            let has_player_projectile = economy
                .fireball_projectiles()
                .iter()
                .any(|projectile| projectile.owner_entity_index == player_slot);
            let has_player_impact = economy.model17_spawned_children().iter().any(|impact| {
                impact.source_class == 10
                    && impact.model == 0
                    && impact.parent_entity_id == player_slot
            });
            if !has_player_projectile && !has_player_impact {
                break;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let mut stable_aimed_bee = None;
        for _ in 0..exact_package_rows.len() {
            let current_row = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter(|bee| bee.active && bee.drawing_enabled && bee.life >= 0)
                .filter_map(|bee| {
                    bee.authored_index()
                        .filter(|row| exact_package_rows.contains(row))
                })
                .min();
            let Some(current_row) = current_row else {
                break;
            };
            let _converged = drive_real_bee_to_fireball_action_for_test(session, current_row);
            stable_aimed_bee = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .find(|bee| {
                    bee.active
                        && bee.drawing_enabled
                        && bee.life >= 0
                        && bee.authored_index() == Some(current_row)
                })
                .copied();
            if stable_aimed_bee.is_some() {
                break;
            }
        }
        let aimed_bee = stable_aimed_bee.unwrap_or_else(|| {
            panic!(
                "no stable current package Bee remains after requested row {requested_authored_index}"
            )
        });
        let aimed_authored_index = aimed_bee
            .authored_index()
            .expect("stable package Bee retains its authored row");
        let (attacker, before, projectile_slots_before, impact_occurrences_before) = {
            let compatibility = session.backend().campaign.level2_compatibility();
            let economy = compatibility.economy();
            let shared = compatibility.shared_spells();
            let player = shared.local_player();
            let holder_slot = player.enabled_spell_holders[0];
            let holder = shared
                .pickups()
                .iter()
                .chain(shared.holders())
                .chain(shared.dynamic_pickups())
                .find(|holder| holder.index == holder_slot)
                .expect("local player retains the acquired Fireball holder");
            assert!(holder.active);
            assert_eq!((holder.class, holder.model, holder.action), (15, 0, 0));
            assert_eq!(
                holder.source_spell_parent_entity_index(),
                player.entity_index
            );
            assert!((0..=2).contains(&holder.level_gate));
            assert!(shared.player_mana() >= holder.max_mana);
            let replaceable_slots = real_level_two_new_event_replaceable_slots_for_test(economy);
            assert!(
                economy.free_slot_count() > 0 || !replaceable_slots.is_empty(),
                "NewEvent admission requires an ordinary free row or a current source-replaceable row: live={:?}",
                economy.live_arena_slots()
            );
            assert!(
                economy
                    .fireball_projectiles()
                    .iter()
                    .all(|projectile| projectile.owner_entity_index != player.entity_index)
            );
            assert!(
                economy
                    .model17_spawned_children()
                    .iter()
                    .all(|impact| impact.parent_entity_id != player.entity_index)
            );
            let before = economy
                .bee_creatures()
                .iter()
                .filter(|bee| {
                    bee.active
                        && bee.drawing_enabled
                        && bee.life >= 0
                        && bee
                            .authored_index()
                            .is_some_and(|row| exact_package_rows.contains(&row))
                })
                .map(|bee| {
                    (
                        bee.authored_index().expect("filtered package Bee row"),
                        bee.source_entity_index,
                        economy.slot_generation(bee.source_entity_index),
                        bee.life,
                    )
                })
                .collect::<Vec<_>>();
            (
                compatibility.state.entity_index,
                before,
                economy
                    .fireball_projectiles()
                    .iter()
                    .map(|projectile| projectile.source_entity_index)
                    .collect::<BTreeSet<_>>(),
                economy
                    .model17_spawned_children()
                    .iter()
                    .map(|impact| {
                        (
                            impact.source_entity_index,
                            economy.slot_generation(impact.source_entity_index),
                        )
                    })
                    .collect::<BTreeSet<_>>(),
            )
        };
        assert!(before.iter().any(|(row, slot, generation, life)| {
            *row == aimed_authored_index
                && *slot == aimed_bee.source_entity_index
                && *generation
                    == session
                        .backend()
                        .campaign
                        .level2_compatibility()
                        .economy()
                        .slot_generation(*slot)
                && *life == aimed_bee.life
        }));

        aim_real_player_fireball_at_bee_for_test(session, aimed_bee);
        session
            .step(
                guard(session),
                GameCommand {
                    select_spell: Some(SemanticId::parse("spell.fireball").unwrap()),
                    cast_selected: true,
                    ..GameCommand::default()
                },
            )
            .unwrap();

        let mut projectile_slot = None;
        let mut saw_class10_impact = false;
        let mut saw_completed_impact_callback = false;
        for _ in 0..=24 {
            let compatibility = session.backend().campaign.level2_compatibility();
            let economy = compatibility.economy();
            projectile_slot = projectile_slot.or_else(|| {
                economy
                    .fireball_projectiles()
                    .iter()
                    .find(|projectile| {
                        !projectile_slots_before.contains(&projectile.source_entity_index)
                            && projectile.owner_entity_index == attacker
                            && projectile.source_subspell_index
                                == crate::level1_mission::FIREBALL_PAYLOAD as u16
                    })
                    .map(|projectile| projectile.source_entity_index)
            });
            let completed_impact_callback = economy
                .model17_spawned_children()
                .iter()
                .find(|impact| {
                    !impact_occurrences_before.contains(&(
                        impact.source_entity_index,
                        economy.slot_generation(impact.source_entity_index),
                    )) && impact.source_class == 10
                        && impact.model == 0
                        && impact.parent_entity_id == attacker
                        && impact.subspell_index == crate::level1_mission::FIREBALL_PAYLOAD as u16
                        && projectile_slot.is_none_or(|projectile_slot| {
                            impact.parent_entity_index == projectile_slot
                        })
                })
                .map(|impact| {
                    projectile_slot = Some(impact.parent_entity_index);
                    saw_class10_impact = true;
                    impact.control_flags & 2 != 0
                })
                .unwrap_or(false);
            let recipients = before
                .iter()
                .filter_map(|&(row, source_slot, generation, life_before)| {
                    economy
                        .bee_creatures()
                        .iter()
                        .find(|bee| {
                            bee.authored_index() == Some(row)
                                && bee.source_entity_index == source_slot
                                && economy.slot_generation(source_slot) == generation
                        })
                        .filter(|bee| {
                            bee.life == life_before.wrapping_sub(250)
                                && bee.damage_attacker_entity_index == attacker
                        })
                        .map(|bee| BeeFireballDamageReceipt {
                            authored_index: row,
                            source_slot,
                            generation,
                            life_before,
                            life_after: bee.life,
                        })
                })
                .collect::<Vec<_>>();
            if !recipients.is_empty() {
                // Under NewEvent's zero-free replacement path the impact can
                // apply this exact mailbox damage and be overwritten before
                // the multi-pass observer sees its typed row.  The public
                // activation plus the player-owned payload projectile (or an
                // observed impact's parent slot) and generation-qualified
                // recipient delta are the durable source identities.
                assert!(projectile_slot.is_some());
                return recipients;
            }
            if completed_impact_callback {
                if saw_completed_impact_callback {
                    return Vec::new();
                }
                saw_completed_impact_callback = true;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let current = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .bee_creatures()
            .iter()
            .filter_map(|bee| {
                bee.authored_index()
                    .filter(|row| exact_package_rows.contains(row))
                    .map(|row| (row, bee.source_entity_index, bee.life, bee.action))
            })
            .collect::<Vec<_>>();
        panic!(
            "ordinary Fireball aimed at Bee {aimed_authored_index} did not damage the current package swarm: projectile={projectile_slot:?}, impact={saw_class10_impact}, before={before:?}, current={current:?}"
        );
    }

    #[test]
    fn campaign_backend_public_fireballs_track_real_level_two_moving_bee_swarm_recipient() {
        const BEE_ROWS: [u16; 9] = [210, 211, 212, 229, 230, 231, 236, 237, 257];

        let root = descriptor_fixture_path();
        let definition = load_mc2_campaign(&root, &default_catalog().unwrap()).unwrap();
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::new(definition),
            75,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .activate_authored_group_prerequisite_for_test(4)
            .unwrap();
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .activate_authored_group_prerequisite_for_test(21)
            .unwrap();
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .activate_authored_group_prerequisite_for_test(17)
            .unwrap();
        assert_eq!(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| bee.authored_index())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(BEE_ROWS)
        );

        let mut terminal = BTreeSet::new();
        let mut exact_damage = 0;
        let first_receipts =
            fire_real_player_fireball_at_bee_swarm_for_test(&mut session, BEE_ROWS[0], &BEE_ROWS);
        for receipt in first_receipts {
            assert_eq!(receipt.life_after, receipt.life_before.wrapping_sub(250));
            exact_damage += receipt.life_before - receipt.life_after;
            if receipt.life_after < 0 {
                terminal.insert((receipt.authored_index, receipt.source_slot));
            }
        }
        let first_impact_occurrences = {
            let economy = session.backend().campaign.level2_compatibility().economy();
            economy
                .model17_spawned_children()
                .iter()
                .map(|impact| {
                    (
                        impact.source_entity_index,
                        economy.slot_generation(impact.source_entity_index),
                    )
                })
                .collect::<Vec<_>>()
        };
        assert!(!first_impact_occurrences.is_empty());

        let second_receipts =
            fire_real_player_fireball_at_bee_swarm_for_test(&mut session, BEE_ROWS[0], &BEE_ROWS);
        for receipt in second_receipts {
            assert_eq!(receipt.life_after, receipt.life_before.wrapping_sub(250));
            exact_damage += receipt.life_before - receipt.life_after;
            if receipt.life_after < 0 {
                terminal.insert((receipt.authored_index, receipt.source_slot));
            }
        }
        let economy = session.backend().campaign.level2_compatibility().economy();
        assert!(first_impact_occurrences.iter().all(|&(slot, generation)| {
            economy.model17_spawned_children().iter().all(|impact| {
                impact.source_entity_index != slot || economy.slot_generation(slot) != generation
            })
        }));

        for _ in 2..16 {
            for receipt in fire_real_player_fireball_at_bee_swarm_for_test(
                &mut session,
                BEE_ROWS[0],
                &BEE_ROWS,
            ) {
                assert_eq!(receipt.life_after, receipt.life_before.wrapping_sub(250));
                exact_damage += receipt.life_before - receipt.life_after;
                if receipt.life_after < 0 {
                    terminal.insert((receipt.authored_index, receipt.source_slot));
                }
            }
            if !terminal.is_empty() {
                break;
            }
        }
        assert!(!terminal.is_empty());
        assert_eq!(exact_damage % 250, 0);

        for _ in 0..24 {
            let live_rows = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| bee.authored_index())
                .collect::<BTreeSet<_>>();
            if terminal.iter().all(|(row, _)| !live_rows.contains(row)) {
                break;
            }
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
        }
        assert!(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .all(|bee| !terminal
                    .iter()
                    .any(|(row, _)| bee.authored_index() == Some(*row)))
        );
        assert!(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .events()
                .iter()
                .any(|event| matches!(
                    event,
                    crate::native_world::Level2EconomyEvent::DeathBurstSpawned {
                        parent_entity_index,
                        ..
                    } if terminal.iter().any(|(_, source_slot)| source_slot == parent_entity_index)
                ))
        );

        let mut saw_miss = false;
        let mut saw_later_hit = false;
        for _ in 0..BEE_ROWS.len() * 16 {
            let aimed_row = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter(|bee| bee.active && bee.drawing_enabled && bee.life >= 0)
                .filter_map(|bee| bee.authored_index().filter(|row| BEE_ROWS.contains(row)))
                .min()
                .expect("moving-swarm miss discriminator retains a live package Bee");
            let receipts =
                fire_real_player_fireball_at_bee_swarm_for_test(&mut session, aimed_row, &BEE_ROWS);
            if receipts.is_empty() {
                saw_miss = true;
            } else {
                for receipt in receipts {
                    assert_eq!(receipt.life_after, receipt.life_before.wrapping_sub(250));
                }
                if saw_miss {
                    saw_later_hit = true;
                    break;
                }
            }
        }
        let census = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .bee_creatures()
            .iter()
            .filter_map(|bee| {
                bee.authored_index()
                    .filter(|row| BEE_ROWS.contains(row))
                    .map(|row| (row, bee.source_entity_index, bee.life, bee.action))
            })
            .collect::<Vec<_>>();
        let economy = session.backend().campaign.level2_compatibility().economy();
        let canonical_slots = economy
            .live_arena_slots()
            .into_iter()
            .collect::<BTreeMap<_, _>>();
        for bee in economy
            .bee_creatures()
            .iter()
            .filter(|bee| bee.active && bee.drawing_enabled)
        {
            assert_eq!(
                canonical_slots.get(&bee.source_entity_index),
                Some(&crate::native_world::Level2DynamicArenaKind::BeeCreature),
                "every live typed Bee must remain the canonical current occupant of its numeric source slot: bee={bee:?}, generation={}, occupant={:?}",
                economy.slot_generation(bee.source_entity_index),
                canonical_slots.get(&bee.source_entity_index),
            );
        }
        assert!(
            saw_miss && saw_later_hit,
            "an ordinary moving-swarm miss must be followed by a later exact package-Bee hit: miss={saw_miss}, later_hit={saw_later_hit}, census={census:?}"
        );
    }

    pub(crate) fn drive_real_level_two_to_final_vault_objective_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
    ) {
        let mut session = session;

        let progress_id = |session: &GameSession<Mc2CampaignBackend>| {
            session
                .snapshot()
                .value
                .objective_progress
                .current_objective
                .map(|id| id.as_str().to_owned())
        };
        let stage_position = |session: &GameSession<Mc2CampaignBackend>, stage_index: usize| {
            let compatibility = session.backend().campaign.level2_compatibility();
            let stage = &compatibility.runtime().stages[stage_index];
            crate::Position {
                x: stage.axis_x.cast_unsigned(),
                y: stage.axis_y.cast_unsigned(),
                z: compatibility.state.position.z,
            }
        };
        let fly_until_stage_complete = |session: &mut GameSession<Mc2CampaignBackend>,
                                        stage_index: usize| {
            let target = stage_position(session, stage_index);
            for _ in 0..640 {
                if session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .runtime()
                    .objectives[0]
                    .stage_selectors[stage_index]
                    == 2
                {
                    return;
                }
                let state = session.backend().campaign.level2_compatibility().state;
                let desired = i16::try_from(crate::heading_for_positions(state.position, target))
                    .expect("source heading is 11-bit");
                let correction = crate::turn_toward(state.yaw, desired, 127);
                session
                    .step(
                        guard(session),
                        GameCommand {
                            longitudinal: LongitudinalControl::Accelerate,
                            roll_axis: correction.clamp(-24, 24) as i8,
                            pitch_axis: -127,
                            ..GameCommand::default()
                        },
                    )
                    .unwrap();
            }
            let compatibility = session.backend().campaign.level2_compatibility();
            panic!(
                "ordinary flight did not complete Level 2 stage {stage_index}: state={:?}, target={target:?}, selectors={:?}",
                compatibility.state,
                &compatibility.runtime().objectives[0].stage_selectors[..5]
            );
        };

        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(
            &compatibility.runtime().objectives[0].stage_selectors[..5],
            &[1, 1, 1, 1, 1]
        );
        assert_eq!(compatibility.level2_selected_objective_stage_state(), 1);
        assert_eq!(
            (
                compatibility.runtime().stages[3].axis_x,
                compatibility.runtime().stages[3].axis_y,
            ),
            (-26_112, -6_912),
            "stage 3 is the package waypoint at tile 154,229"
        );
        assert_eq!(
            progress_id(&session).as_deref(),
            Some("objective.reach.payahandra_ruins")
        );

        fly_until_stage_complete(&mut session, 3);
        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(
            &compatibility.runtime().objectives[0].stage_selectors[..5],
            &[1, 1, 1, 2, 1]
        );
        assert_eq!(
            (
                compatibility.runtime().stages[0].axis_x,
                compatibility.runtime().stages[0].axis_y,
            ),
            (512, -26_624),
            "stage 0 is the package waypoint at tile 2,152"
        );
        assert_eq!(
            progress_id(&session).as_deref(),
            Some("objective.reach.sight_beacon")
        );
        assert_eq!(
            session.snapshot().value.objective_progress.completed_count,
            1
        );

        session
            .step(guard(&session), GameCommand::default())
            .unwrap();
        let compatibility = session.backend().campaign.level2_compatibility();
        assert!(compatibility.dispatch_events().iter().any(|event| matches!(
            event,
            crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                source_slot: 32,
                group: 8,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [153, 154]
        )));
        assert_eq!(compatibility.economy().authored_model45().len(), 2);
        assert!(
            compatibility
                .economy()
                .authored_model45()
                .iter()
                .all(|source| source.active && !source.drawing_enabled),
            "the ordinary slot-32 turn hides both group-8 vault rows after their same-pass callbacks"
        );

        fly_until_stage_complete(&mut session, 0);
        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(
            &compatibility.runtime().objectives[0].stage_selectors[..5],
            &[2, 1, 1, 2, 1]
        );
        assert_eq!(
            progress_id(&session).as_deref(),
            Some("objective.defeat.nyphur")
        );
        assert_eq!(
            session.snapshot().value.objective_progress.completed_count,
            2
        );
        assert!(
            compatibility
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                        group: 8,
                        ..
                    }
                ))
        );

        const NYPHUR_SLOT: u16 = 112;
        let nyphur_player_state = |session: &GameSession<Mc2CampaignBackend>| {
            session
                .backend()
                .campaign
                .level2_compatibility()
                .players()
                .iter()
                .find(|player| player.entity_index == NYPHUR_SLOT)
                .and_then(|player| player.banishment_state_0x006)
        };
        let nyphur_action = |session: &GameSession<Mc2CampaignBackend>| {
            session
                .backend()
                .campaign
                .level2_compatibility()
                .entities()
                .iter()
                .find(|entity| {
                    entity.active
                        && entity.index == NYPHUR_SLOT
                        && entity.class == 3
                        && entity.model == 1
                })
                .map(|entity| entity.action)
        };
        let aim_player_at_nyphur = |session: &mut GameSession<Mc2CampaignBackend>| {
            let (target, player_slot, player_fov) = {
                let compatibility = session.backend().campaign.level2_compatibility();
                (
                    compatibility
                        .entities()
                        .iter()
                        .find(|entity| {
                            entity.active
                                && entity.index == NYPHUR_SLOT
                                && entity.class == 3
                                && entity.model == 1
                        })
                        .cloned()
                        .expect("real package Nyphur remains live before the cast"),
                    compatibility.state.entity_index,
                    compatibility.state.entity_fov,
                )
            };
            let collision = target.collision_target();
            let mut predicted_target = crate::Position {
                z: target
                    .position
                    .z
                    .wrapping_add(collision.collision_vertical_offset)
                    .wrapping_sub(crate::level1_mission::FIREBALL_COLLISION_VERTICAL_OFFSET),
                ..target.position
            };
            crate::move_entity(
                &mut predicted_target,
                target.yaw,
                target.pitch,
                target.actual_speed,
            );
            let current_launch = crate::Position {
                z: session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .state
                    .position
                    .z
                    .wrapping_add(player_fov),
                ..session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .state
                    .position
            };
            let approach_yaw =
                crate::level1_mission::projectile_guidance_angles(current_launch, predicted_target)
                    .0;
            let crossing_distance = crate::level1_mission::FIREBALL_SPEED
                .saturating_add(crate::level1_mission::FIREBALL_COLLISION_HALF_WIDTH)
                .saturating_add(collision.collision_half_width)
                .saturating_sub(1);
            let mut player_position = predicted_target;
            crate::move_entity(
                &mut player_position,
                approach_yaw.wrapping_add(1024),
                0,
                crossing_distance,
            );
            player_position.z = crate::FlightWorld::ground_height(
                session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .canonical_terrain(),
                player_position,
            )
            .wrapping_add(256);
            let mut launch_position = player_position;
            let provisional_launch = crate::Position {
                z: launch_position.z.wrapping_add(player_fov),
                ..launch_position
            };
            let provisional = crate::level1_mission::projectile_guidance_angles(
                provisional_launch,
                predicted_target,
            );
            let direction_bits = session
                .backend()
                .campaign
                .level2_compatibility()
                .shared_spells()
                .player_entity()
                .control_flags
                & 0x0300;
            let hand_yaw = if direction_bits & 0x0100 != 0 {
                Some(provisional.0.wrapping_sub(512))
            } else if direction_bits & 0x0200 != 0 {
                Some(provisional.0.wrapping_add(512))
            } else {
                None
            };
            if let Some(hand_yaw) = hand_yaw {
                crate::move_entity(&mut launch_position, hand_yaw, 0, 256);
                if crate::FlightWorld::ground_height(
                    session
                        .backend()
                        .campaign
                        .level2_compatibility()
                        .canonical_terrain(),
                    launch_position,
                ) > launch_position.z
                {
                    launch_position = player_position;
                }
            }
            launch_position.z = launch_position.z.wrapping_add(player_fov);
            let (yaw, pitch) = crate::level1_mission::projectile_guidance_angles(
                launch_position,
                predicted_target,
            );
            let compatibility = session.backend_mut().campaign.level2_compatibility_mut();
            compatibility
                .set_level2_entity_position(player_slot, player_position)
                .expect("position the real player at the proven incoming-combat boundary");
            compatibility.set_level2_player_aim_for_test(yaw, pitch);
        };

        assert_eq!(nyphur_player_state(&session), Some(1));
        assert_eq!(nyphur_action(&session), Some(1));
        for cast_index in 0..32 {
            if nyphur_action(&session) == Some(2) {
                break;
            }
            let life_before = session
                .backend()
                .campaign
                .level2_compatibility()
                .nyphur_common_upkeep()
                .expect("qualified Nyphur common carrier")
                .life;
            let projectile_slots_before = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .fireball_projectiles()
                .iter()
                .map(|projectile| projectile.source_entity_index)
                .collect::<BTreeSet<_>>();
            let impact_slots_before = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .model17_spawned_children()
                .iter()
                .map(|impact| impact.source_entity_index)
                .collect::<BTreeSet<_>>();
            aim_player_at_nyphur(&mut session);
            session
                .step(
                    guard(&session),
                    GameCommand {
                        select_spell: Some(SemanticId::parse("spell.fireball").unwrap()),
                        cast_selected: true,
                        ..GameCommand::default()
                    },
                )
                .unwrap();
            let mut impact_life = None;
            let mut projectile_slot = None;
            let mut saw_class10_impact = false;
            for _ in 0..12 {
                let compatibility = session.backend().campaign.level2_compatibility();
                projectile_slot = projectile_slot.or_else(|| {
                    compatibility
                        .economy()
                        .fireball_projectiles()
                        .iter()
                        .find(|projectile| {
                            !projectile_slots_before.contains(&projectile.source_entity_index)
                                && projectile.owner_entity_index == compatibility.state.entity_index
                                && projectile.source_subspell_index
                                    == crate::level1_mission::FIREBALL_PAYLOAD as u16
                        })
                        .map(|projectile| projectile.source_entity_index)
                });
                saw_class10_impact |= projectile_slot.is_some_and(|projectile_slot| {
                    compatibility
                        .economy()
                        .model17_spawned_children()
                        .iter()
                        .any(|impact| {
                            !impact_slots_before.contains(&impact.source_entity_index)
                                && impact.source_class == 10
                                && impact.model == 0
                                && impact.parent_entity_index == projectile_slot
                                && impact.subspell_index
                                    == crate::level1_mission::FIREBALL_PAYLOAD as u16
                        })
                });
                let life = compatibility
                    .nyphur_common_upkeep()
                    .expect("Nyphur common carrier survives until lethal impact")
                    .life;
                if life < life_before {
                    impact_life = Some(life);
                    break;
                }
                session
                    .step(guard(&session), GameCommand::default())
                    .unwrap();
            }
            assert!(
                impact_life.is_some(),
                "ordinary semantic Fireball cast {cast_index} did not reach Nyphur's source mailbox"
            );
            assert!(
                saw_class10_impact,
                "ordinary semantic Fireball cast {cast_index} did not emit the source class-10/model-0 impact"
            );
            if impact_life.is_some_and(|life| life < 0) {
                session
                    .step(guard(&session), GameCommand::default())
                    .unwrap();
                break;
            }
        }
        assert_eq!(nyphur_action(&session), Some(2));
        assert_eq!(
            nyphur_player_state(&session),
            Some(1),
            "lethal entity state alone must not satisfy the rival objective"
        );
        assert_eq!(
            &session
                .backend()
                .campaign
                .level2_compatibility()
                .runtime()
                .objectives[0]
                .stage_selectors[..5],
            &[2, 1, 1, 2, 1]
        );

        for _ in 0..512 {
            if nyphur_player_state(&session) == Some(0) {
                break;
            }
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
        }
        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(nyphur_player_state(&session), Some(0));
        assert_eq!(
            &compatibility.runtime().objectives[0].stage_selectors[..5],
            &[2, 2, 1, 2, 1]
        );
        assert_eq!(
            progress_id(&session).as_deref(),
            Some("objective.clear.plague_bees")
        );
        assert_eq!(
            session.snapshot().value.objective_progress.completed_count,
            3
        );

        const PLAGUE_BEE_ROWS: [u16; 6] = [229, 230, 231, 236, 237, 257];
        for _ in 0..4 {
            let bee_rows = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| bee.authored_index())
                .collect::<BTreeSet<_>>();
            if bee_rows == BTreeSet::from(PLAGUE_BEE_ROWS) {
                break;
            }
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
        }
        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(
            compatibility
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| bee.authored_index())
                .collect::<BTreeSet<_>>(),
            BTreeSet::from(PLAGUE_BEE_ROWS),
            "the ordinary row-206/group-17 producer materializes exactly the package plague Bees"
        );
        assert!(compatibility.dispatch_events().iter().any(|event| matches!(
            event,
            crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                group: 17,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [208, 236, 237, 257]
        )));
        assert!(compatibility.dispatch_events().iter().any(|event| matches!(
            event,
            crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                group: 21,
                authored_indices,
                ..
            } if authored_indices.as_ref() == [229, 230, 231]
        )));
        assert_eq!(
            &compatibility.runtime().objectives[0].stage_selectors[..5],
            &[2, 2, 1, 2, 1],
            "materializing the two production plague groups must not complete their absence objective"
        );

        let first_bee_position = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .bee_creatures()
            .iter()
            .find(|bee| bee.authored_index() == Some(PLAGUE_BEE_ROWS[0]))
            .expect("first package plague Bee is live")
            .position;
        position_player_at_bee_fireball_boundary_for_test(
            &mut session,
            crate::Position {
                x: first_bee_position.x.wrapping_add(20_000),
                y: first_bee_position.y.wrapping_add(20_000),
                z: first_bee_position.z,
            },
        );
        for _ in 0..64 {
            let state = session.backend().campaign.level2_compatibility().state;
            if state.target_speed == 0 && state.actual_speed == 0 {
                break;
            }
            let longitudinal = if state.target_speed > 0 {
                LongitudinalControl::Decelerate
            } else if state.target_speed < 0 {
                LongitudinalControl::Accelerate
            } else {
                LongitudinalControl::Coast
            };
            session
                .step(
                    guard(&session),
                    GameCommand {
                        longitudinal,
                        ..GameCommand::default()
                    },
                )
                .unwrap();
        }
        let stopped = session.backend().campaign.level2_compatibility().state;
        assert_eq!(
            (stopped.target_speed, stopped.actual_speed),
            (0, 0),
            "ordinary flight input stops before source-qualified Bee casting"
        );

        const ALL_PACKAGE_BEE_ROWS: [u16; 12] =
            [210, 211, 212, 229, 230, 231, 236, 237, 257, 307, 308, 312];

        // Keep one complete public semantic route in this causal test. Source
        // guidance supplies the launch angles, then production owns class-9
        // construction, class-10 impact, target selection, and the mailbox.
        let first_bee =
            drive_real_bee_to_fireball_action_for_test(&mut session, PLAGUE_BEE_ROWS[0]);
        let first_life_before = first_bee.life;
        let other_lives_before = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .bee_creatures()
            .iter()
            .filter_map(|bee| {
                bee.authored_index()
                    .filter(|row| *row != PLAGUE_BEE_ROWS[0])
                    .map(|row| (row, bee.life))
            })
            .collect::<Vec<_>>();
        let public_hit =
            fire_real_player_fireball_at_bee_for_test(&mut session, PLAGUE_BEE_ROWS[0]);
        assert_eq!(public_hit.life, first_life_before.wrapping_sub(250));
        for (other_row, other_life) in other_lives_before {
            assert_eq!(
                session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .bee_creatures()
                    .iter()
                    .find(|bee| bee.authored_index() == Some(other_row))
                    .map(|bee| bee.life),
                Some(other_life),
                "the public collision selects only row 229"
            );
        }

        // Subsequent public casts retain their source-derived aim, while the
        // real class-10 overlap decides which current package Bee receives
        // each pulse. Ordinary Bee callbacks still own damage, death phases,
        // hide, following-pass reclaim, allocator retry, and objective census.
        let mut reclaimed_rows = BTreeSet::new();
        let mut terminal_rows = BTreeSet::new();
        let mut retired_rows = BTreeSet::new();
        let mut hit_casts = 1_usize;
        let mut missed_casts = 0_usize;
        let mut recipient_hits = 1_usize;
        for _ in 0..ALL_PACKAGE_BEE_ROWS.len() {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .runtime()
                .objectives[0]
                .stage_selectors[2]
                == 2
            {
                break;
            }
            let mut next_bee = None;
            for _ in 0..4 {
                next_bee = session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .bee_creatures()
                    .iter()
                    .filter(|bee| bee.active && bee.drawing_enabled && bee.life >= 0)
                    .filter_map(|bee| {
                        bee.authored_index()
                            .filter(|row| ALL_PACKAGE_BEE_ROWS.contains(row))
                    })
                    .min();
                if next_bee.is_some()
                    || session
                        .backend()
                        .campaign
                        .level2_compatibility()
                        .runtime()
                        .objectives[0]
                        .stage_selectors[2]
                        == 2
                {
                    break;
                }
                session
                    .step(guard(&session), GameCommand::default())
                    .unwrap();
            }
            if next_bee.is_none() && BTreeSet::from(PLAGUE_BEE_ROWS).is_subset(&retired_rows) {
                // The final Bee can be physically reclaimed before the
                // following objective-service pass observes the empty
                // package census.  Advance only that established death-tail
                // bound, checking the selector before every ordinary step so
                // the next objective stage cannot be consumed here.
                for _ in 0..24 {
                    if session
                        .backend()
                        .campaign
                        .level2_compatibility()
                        .runtime()
                        .objectives[0]
                        .stage_selectors[2]
                        == 2
                    {
                        break;
                    }
                    next_bee = session
                        .backend()
                        .campaign
                        .level2_compatibility()
                        .economy()
                        .bee_creatures()
                        .iter()
                        .filter(|bee| bee.active && bee.drawing_enabled && bee.life >= 0)
                        .filter_map(|bee| {
                            bee.authored_index()
                                .filter(|row| ALL_PACKAGE_BEE_ROWS.contains(row))
                        })
                        .min();
                    if next_bee.is_some() {
                        break;
                    }
                    session
                        .step(guard(&session), GameCommand::default())
                        .unwrap();
                }
                if session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .runtime()
                    .objectives[0]
                    .stage_selectors[2]
                    == 2
                {
                    break;
                }
            }
            let Some(authored_index) = next_bee else {
                break;
            };
            assert!(ALL_PACKAGE_BEE_ROWS.contains(&authored_index));
            for _pulse in 0..16 {
                let receipts = fire_real_player_fireball_at_bee_swarm_for_test(
                    &mut session,
                    authored_index,
                    &ALL_PACKAGE_BEE_ROWS,
                );
                if receipts.is_empty() {
                    missed_casts += 1;
                } else {
                    hit_casts += 1;
                    recipient_hits += receipts.len();
                }
                for receipt in receipts {
                    assert!(ALL_PACKAGE_BEE_ROWS.contains(&receipt.authored_index));
                    assert_eq!(receipt.life_after, receipt.life_before.wrapping_sub(250));
                    if receipt.life_after < 0 {
                        terminal_rows.insert(receipt.authored_index);
                        retired_rows.insert(receipt.authored_index);
                    }
                }
                let requested_is_current = session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .bee_creatures()
                    .iter()
                    .any(|bee| {
                        bee.authored_index() == Some(authored_index)
                            && bee.active
                            && bee.drawing_enabled
                            && bee.life >= 0
                    });
                if terminal_rows.contains(&authored_index) || !requested_is_current {
                    break;
                }
                if session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .runtime()
                    .objectives[0]
                    .stage_selectors[2]
                    == 2
                {
                    break;
                }
            }
            let census = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| {
                    bee.authored_index()
                        .filter(|row| ALL_PACKAGE_BEE_ROWS.contains(row))
                        .map(|row| {
                            (
                                row,
                                bee.source_entity_index,
                                bee.life,
                                bee.action,
                                bee.active,
                                bee.drawing_enabled,
                            )
                        })
                })
                .collect::<Vec<_>>();
            let requested_is_current = census.iter().any(
                |&(row, _source_slot, life, _action, active, drawing_enabled)| {
                    row == authored_index && active && drawing_enabled && life >= 0
                },
            );
            assert!(
                terminal_rows.contains(&authored_index) || !requested_is_current,
                "source-guided public casts exhausted the existing 16-attempt budget while Bee {authored_index} remained current: hit_casts={hit_casts}, missed_casts={missed_casts}, recipient_hits={recipient_hits}, census={census:?}"
            );
            if !requested_is_current {
                retired_rows.insert(authored_index);
            }

            let mut objective_completed = false;
            for _ in 0..24 {
                if session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .runtime()
                    .objectives[0]
                    .stage_selectors[2]
                    == 2
                {
                    objective_completed = true;
                    break;
                }
                if session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .bee_creatures()
                    .iter()
                    .all(|bee| bee.authored_index() != Some(authored_index))
                {
                    break;
                }
                session
                    .step(guard(&session), GameCommand::default())
                    .unwrap();
            }
            let current = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .find(|bee| bee.authored_index() == Some(authored_index))
                .copied();
            if objective_completed {
                assert!(
                    current.is_none_or(|bee| !bee.active || !bee.drawing_enabled),
                    "the final plague Bee is absent from the live census at objective completion: {current:?}"
                );
            } else {
                assert!(
                    current.is_none(),
                    "plague Bee {authored_index} reaches following-pass reclaim: {current:?}"
                );
                reclaimed_rows.insert(authored_index);
            }
        }

        assert!(
            BTreeSet::from(PLAGUE_BEE_ROWS).is_subset(&retired_rows),
            "all six production plague Bees retire from the authoritative live census through ordinary combat/death: retired={retired_rows:?}, terminal={terminal_rows:?}"
        );
        assert!(
            BTreeSet::from([229, 230, 231, 236, 237]).is_subset(&reclaimed_rows),
            "the first five production plague Bees reach following-pass physical reclaim"
        );
        let compatibility = session.backend().campaign.level2_compatibility();
        let live_bee_rows = compatibility
            .economy()
            .bee_creatures()
            .iter()
            .filter(|bee| bee.active && bee.drawing_enabled)
            .filter_map(|bee| bee.authored_index())
            .collect::<BTreeSet<_>>();
        assert!(BTreeSet::from(ALL_PACKAGE_BEE_ROWS).is_disjoint(&live_bee_rows));
        assert!(
            compatibility.economy().authored_model45().is_empty(),
            "the real group-8 vault rows reach ordinary hide and following-pass reclaim before their final absence objective"
        );
        assert_eq!(
            &compatibility.runtime().objectives[0].stage_selectors[..5],
            &[2, 2, 2, 2, 1]
        );
        assert_eq!(
            progress_id(&session).as_deref(),
            Some("objective.clear.payahandra_vaults")
        );
        assert_eq!(
            session.snapshot().value.objective_progress.completed_count,
            4
        );
    }

