    #[test]
    fn campaign_backend_level_three_dragon_observer_pages_past_dense_effect_noise() {
        let before = crate::campaign::journal::EffectJournal::new();
        let mut after = before.clone();
        for sequence in 0..65_u32 {
            after.append_flight(
                sequence,
                FlightEvent::PrepareSound {
                    audio_site: crate::MissionAudioSite::FireballImpact,
                    entity_index: 149,
                    player_index: -1,
                    sound_id: 3,
                },
            );
        }
        let missing_impact = after.clone();
        after.append_flight(
            65,
            FlightEvent::PrepareSound {
                audio_site: crate::MissionAudioSite::FireballImpact,
                entity_index: 298,
                player_index: -1,
                sound_id: 3,
            },
        );

        let records = level_three_effect_records_after_for_test(&before, &after)
            .expect("dense retained effects remain exhaustively page-readable");
        assert_eq!(records.len(), 66);
        assert_eq!(records.first().map(|record| record.sequence), Some(0));
        assert_eq!(records.last().map(|record| record.sequence), Some(65));
        assert_eq!(
            records
                .iter()
                .filter(|record| matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                        audio_site: crate::MissionAudioSite::FireballImpact,
                        entity_index: 298,
                        sound_id: 3,
                        ..
                    })
                ))
                .count(),
            1,
            "the unique impact after 65 preceding effects must be read from the second page"
        );
        assert!(
            level_three_effect_records_after_for_test(&before, &missing_impact)
                .expect("dense noise remains page-readable")
                .iter()
                .all(|record| !matches!(
                    record.effect,
                    crate::campaign::journal::CampaignEffect::Flight(FlightEvent::PrepareSound {
                        audio_site: crate::MissionAudioSite::FireballImpact,
                        entity_index: 298,
                        sound_id: 3,
                        ..
                    })
                )),
            "dense noise without the exact impact receipt must remain negative"
        );
    }

    #[test]
    fn campaign_backend_level_three_transient_dragon_impact_is_attributed_from_one_numeric_step() {
        let root = level_three_descriptor_fixture_path();
        let catalog = default_catalog().unwrap();
        let definition = Arc::new(load_mc2_campaign(&root, &catalog).unwrap());
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            69,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .activate_authored_group_prerequisite_for_test(1)
            .unwrap();
        let player = session
            .backend()
            .campaign
            .level2_compatibility()
            .state
            .entity_index;
        let skeleton_slots = session
            .backend()
            .campaign
            .level2_compatibility()
            .entities()
            .iter()
            .filter(|entity| {
                entity.active && entity.index < player && entity.class == 5 && entity.model == 9
            })
            .take(2)
            .map(|entity| entity.index)
            .collect::<Vec<_>>();
        assert_eq!(skeleton_slots.len(), 2);
        for source_slot in &skeleton_slots {
            session
                .backend_mut()
                .campaign
                .level2_compatibility_mut()
                .stage_imported_skeleton_fireball_damage_for_test(*source_slot, player, 1_500)
                .unwrap();
        }
        for _ in 0..32 {
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
            if skeleton_slots.iter().all(|slot| {
                !session.backend().campaign.level2_compatibility().entities()[usize::from(*slot)]
                    .active
            }) {
                break;
            }
        }
        assert!(skeleton_slots.iter().all(|slot| {
            !session.backend().campaign.level2_compatibility().entities()[usize::from(*slot)].active
        }));
        let root = level_three_dragon_fireball_targets(&session)
            .into_iter()
            .filter(|target| target.source_slot == target.root_slot)
            .min_by_key(|target| target.source_slot)
            .expect("one qualified guardian root is active");
        let root_yaw = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .authored_class5()
            .iter()
            .find(|source| source.source_entity_index == root.root_slot)
            .expect("the selected guardian root retains its source row")
            .yaw;
        let mut player_position = root.position;
        crate::move_entity(&mut player_position, root_yaw, 0, 2_048);
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .set_level2_entity_position(player, player_position)
            .unwrap();
        let reserved_slots = [skeleton_slots[0], skeleton_slots[1]];
        {
            let mut economy = session
                .backend_mut()
                .campaign
                .level2_compatibility_mut()
                .economy_mut();
            economy.exhaust_new_event_capacity_for_test();
            assert!(economy.restore_new_event_slot_for_test(reserved_slots[1]));
            assert!(economy.restore_new_event_slot_for_test(reserved_slots[0]));
        }

        let mut launched = None;
        for _ in 0..=64 {
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
            launched = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .fireball_projectiles()
                .iter()
                .find(|projectile| {
                    projectile.active
                        && projectile.owner_entity_index == root.root_slot
                        && projectile.origin
                            == crate::native_world::FireballProjectileOrigin::Dragon
                })
                .copied();
            if launched.is_some() {
                break;
            }
        }
        let projectile = launched.expect("the real Dragon action-2 callback launches class 9");
        let mut collision_position = projectile.position;
        for _ in 0..4 {
            let (_, desired_pitch) = crate::level1_mission::projectile_guidance_angles(
                projectile.position,
                collision_position,
            );
            let next_pitch = projectile.pitch.wrapping_add(crate::turn_toward(
                projectile.pitch,
                desired_pitch,
                22,
            )) & crate::ANGLE_MASK;
            collision_position = projectile.position;
            crate::move_entity(
                &mut collision_position,
                projectile.yaw,
                next_pitch,
                projectile.actual_speed,
            );
        }
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .set_level2_entity_position(player, collision_position)
            .unwrap();
        {
            let state = &mut session
                .backend_mut()
                .campaign
                .level2_compatibility_mut()
                .state;
            state.target_speed = 0;
            state.actual_speed = 0;
            state.strafe_speed = 0;
            state.recoil_speed = 0;
            state.impulse_x = 0;
            state.impulse_y = 0;
            state.impulse_z = 0;
            state.skip_flight_once = true;
        }
        let before = session.backend().campaign.level2_compatibility().clone();
        let event_start = before.economy().events().len();
        let projectile_generation = before
            .economy()
            .slot_generation(projectile.source_entity_index);
        session
            .step(guard(&session), GameCommand::default())
            .unwrap();
        let after = session.backend().campaign.level2_compatibility().clone();
        let damage = after.economy().events()[event_start..]
            .iter()
            .find_map(|event| match event {
                crate::native_world::Level2EconomyEvent::DamageApplied {
                    target_entity_index,
                    attacker_entity_index,
                    damage: 500,
                    lethal: false,
                } if *target_entity_index == player => Some(*attacker_entity_index),
                _ => None,
            });
        if damage.is_none() {
            eprintln!(
                "numeric Dragon collision miss: projectile_before={projectile:?} collision_position={collision_position:?} player_before={:?} player_after={:?} projectile_after={:?} impacts={:?} events={:?} dispatch={:?}",
                before.state.position,
                after.state.position,
                after.economy().fireball_projectiles(),
                after.economy().model17_spawned_children(),
                &after.economy().events()[event_start..],
                after.dispatch_events(),
            );
        }
        let damage =
            damage.expect("the numeric class-10 callback reaches the real player consumer");
        assert_eq!(damage, root.root_slot);
        let impact_slot = reserved_slots[1];
        let impact_dispatches = after
            .dispatch_events()
            .iter()
            .filter(|event| {
                matches!(
                    event,
                    crate::native_world::Level2DispatchEvent::DynamicArena {
                        source_slot,
                        kind: crate::native_world::Level2DynamicArenaKind::Model17SpawnedChild,
                        ..
                    } if *source_slot == impact_slot
                )
            })
            .count();
        let stale_economy_sounds = after.economy().events()[event_start..]
            .iter()
            .filter(|event| {
                matches!(
                    event,
                    crate::native_world::Level2EconomyEvent::FireSphereCollisionSound {
                        source_entity_index,
                        ..
                    } if *source_entity_index == impact_slot
                )
            })
            .count();
        let impact_sounds = level_three_effect_records_after_for_test(
            before.effect_journal(),
            after.effect_journal(),
        )
        .expect("the numeric impact effects remain exhaustively page-readable")
        .iter()
        .filter(|record| {
            matches!(
                record.effect,
                crate::campaign::journal::CampaignEffect::Flight(
                    FlightEvent::PrepareSound {
                        audio_site: crate::MissionAudioSite::FireballImpact,
                        entity_index,
                        sound_id: 3,
                        ..
                    }
                ) if entity_index == impact_slot
            )
        })
        .count();
        let projectile_current = after
            .economy()
            .fireball_projectiles()
            .iter()
            .any(|current| {
                current.active
                    && current.source_entity_index == projectile.source_entity_index
                    && after.economy().slot_generation(current.source_entity_index)
                        == projectile_generation
            });
        eprintln!(
            "transient Dragon impact trace: projectile=(slot={},generation={},target={},life={},phase={}) terminal={} impact=(slot={},generation_before={},generation_after={},dispatches={},sounds={})",
            projectile.source_entity_index,
            projectile_generation,
            projectile.target_source_entity_index,
            projectile.life,
            projectile.phase,
            !projectile_current,
            impact_slot,
            before.economy().slot_generation(impact_slot),
            after.economy().slot_generation(impact_slot),
            impact_dispatches,
            impact_sounds,
        );
        assert_eq!(impact_dispatches, 1);
        assert_eq!(
            stale_economy_sounds, 0,
            "the class-10 impact audio is a flight journal receipt, not an economy sound event"
        );
        assert_eq!(impact_sounds, 1);
        assert!(level_three_unique_transient_dragon_impact_for_test(
            1,
            !projectile_current,
            impact_dispatches,
            impact_sounds,
            1,
            0,
            before.economy().slot_generation(impact_slot),
            after.economy().slot_generation(impact_slot),
        ));
        assert_eq!(
            level_three_source_attributed_retreat_damage_for_test(&before, &after),
            Some(500),
            "the real same-step transient impact must satisfy the retreat observer"
        );
    }

    #[test]
    fn campaign_backend_signed_flight_controller_brakes_without_crossing_into_reverse() {
        let mut state = crate::FlightState::default();
        state.yaw = 0;
        state.target_speed = -80;
        state.actual_speed = -80;
        let braking_reverse = level_three_source_safe_flight_command(state, 512, false);
        assert_eq!(
            braking_reverse.longitudinal,
            LongitudinalControl::Accelerate
        );
        assert_eq!(braking_reverse.roll_axis, 0);

        state.target_speed = 0;
        state.actual_speed = -16;
        let settling_reverse = level_three_source_safe_flight_command(state, 512, false);
        assert_eq!(settling_reverse.longitudinal, LongitudinalControl::Coast);
        assert_eq!(settling_reverse.roll_axis, 0);

        state.actual_speed = 0;
        let turning_at_rest = level_three_source_safe_flight_command(state, 512, false);
        assert_eq!(turning_at_rest.longitudinal, LongitudinalControl::Coast);
        assert_eq!(turning_at_rest.roll_axis, 24);

        state.yaw = 500;
        let forward_only_when_aligned = level_three_source_safe_flight_command(state, 512, false);
        assert_eq!(
            forward_only_when_aligned.longitudinal,
            LongitudinalControl::Accelerate
        );
        assert_eq!(forward_only_when_aligned.roll_axis, 12);

        state.target_speed = 80;
        state.actual_speed = 80;
        let braking_forward = level_three_source_safe_flight_command(state, 0, true);
        assert_eq!(
            braking_forward.longitudinal,
            LongitudinalControl::Decelerate
        );
        assert_eq!(braking_forward.roll_axis, 0);
    }

    #[test]
    fn campaign_backend_signed_retreat_outruns_a_moving_dragon_with_source_bound() {
        #[derive(Clone, Copy)]
        struct OpenWorld;

        impl crate::FlightWorld for OpenWorld {
            fn ground_height(&self, _position: crate::Position) -> i16 {
                0
            }

            fn ceiling_height(&self, _position: crate::Position) -> Option<i16> {
                None
            }

            fn material_mask(&self, _position: crate::Position) -> u32 {
                0
            }

            fn angle_flags(&self, _tile: crate::Tile) -> u8 {
                0
            }
        }

        fn separation(player: crate::Position, dragon: crate::Position) -> u32 {
            let dx = i32::from(dragon.x.wrapping_sub(player.x).cast_signed());
            let dy = i32::from(dragon.y.wrapping_sub(player.y).cast_signed());
            crate::legacy_sqrt(
                dx.wrapping_mul(dx)
                    .wrapping_add(dy.wrapping_mul(dy))
                    .cast_unsigned(),
            )
        }

        fn first_clear_turn(bound: usize) -> Option<usize> {
            let mut player = crate::FlightState::default();
            player.position = crate::Position {
                x: 32_768,
                y: 32_768,
                z: 1_280,
            };
            player.yaw = 0;
            player.pitch_accumulator = -254;
            player.display_pitch = (-254_i16) & crate::ANGLE_MASK;
            player.roll_accumulator = -254;
            player.target_speed = -crate::SPEED_LIMIT;
            player.actual_speed = -crate::SPEED_LIMIT;
            let mut dragon = crate::Position {
                x: player.position.x,
                y: player.position.y.wrapping_sub(883),
                z: 0,
            };
            let retreat_heading =
                i16::try_from(crate::heading_for_positions(dragon, player.position)).unwrap();

            for turn in 0..=bound {
                if separation(player.position, dragon)
                    > crate::level1_mission::PROJECTILE_ACQUISITION_RANGE
                {
                    return Some(turn);
                }
                let dragon_heading =
                    i16::try_from(crate::heading_for_positions(dragon, player.position)).unwrap();
                crate::move_entity(&mut dragon, dragon_heading, 0, 30);
                let command =
                    level_three_source_safe_flight_command(player, retreat_heading, false);
                let latched = crate::latch_command(&mut player, campaign_player_command(&command));
                crate::step_entity_pass(
                    &mut player,
                    latched,
                    crate::FlightProfile::OUTDOOR,
                    &OpenWorld,
                );
            }
            None
        }

        let initial_separation = 883;
        let old_bound = usize::from(crate::level1_mission::FIREBALL_LIFETIME_TICKS as u16)
            + usize::try_from(DRAGON_FIREBALL_TRAVEL_RANGE / (80 - 30)).unwrap()
            + 64;
        assert_eq!(first_clear_turn(old_bound), None);

        let source_bound = level_three_dragon_retreat_bound(initial_separation);
        let clear_turn = first_clear_turn(source_bound)
            .expect("source-derived closure bound outruns the moving Dragon");
        assert!(clear_turn > old_bound);
        assert!(clear_turn <= source_bound - (22 + 10 + 1));
    }

    #[test]
    fn campaign_backend_level_three_recovery_route_avoids_guardian_acquisition_disks() {
        let root = level_three_descriptor_fixture_path();
        let catalog = default_catalog().unwrap();
        let definition = Arc::new(load_mc2_campaign(&root, &catalog).unwrap());
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            66,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        let guardian_spawns = level_three_guardian_spawn_positions_for_test(&session);
        let castle = valid_level_three_castle_sites_for_test(&session)
            .into_iter()
            .filter(|site| {
                level_three_castle_healing_footprint_outside_dragon_range_for_test(
                    *site,
                    &guardian_spawns,
                )
            })
            .min_by_key(|site| {
                let dx = i32::from(site.x.wrapping_sub(27_648).cast_signed());
                let dy = i32::from(site.y.wrapping_sub(53_760).cast_signed());
                dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy))
            })
            .expect("qualified Level 3 retains a production-admitted safe Castle footprint");
        assert!(
            level_three_castle_healing_footprint_outside_dragon_range_for_test(
                castle,
                &guardian_spawns,
            )
        );

        // Put a trace-shaped recovery endpoint just outside the first root on
        // the side opposite the Castle.  Both endpoints are safe, but their
        // old direct chord necessarily crosses the acquisition disk.
        let first_root = guardian_spawns[0];
        let away = i16::try_from(crate::heading_for_positions(castle, first_root)).unwrap();
        let mut origin = first_root;
        crate::move_entity(
            &mut origin,
            away,
            0,
            i16::try_from(crate::level1_mission::PROJECTILE_ACQUISITION_RANGE + 768).unwrap(),
        );
        origin.z = session
            .backend()
            .campaign
            .level2_compatibility()
            .canonical_terrain()
            .ground_height(origin)
            .wrapping_add(256);
        assert!(level_three_position_outside_dragon_range_for_test(
            origin,
            &guardian_spawns
        ));

        let direct_heading = i16::try_from(crate::heading_for_positions(origin, castle)).unwrap();
        let mut direct = origin;
        let mut direct_enters_guardian_range = false;
        for _ in 0..128 {
            crate::move_entity(&mut direct, direct_heading, 0, 256);
            if !level_three_position_outside_dragon_range_for_test(direct, &guardian_spawns) {
                direct_enters_guardian_range = true;
                break;
            }
        }
        assert!(
            direct_enters_guardian_range,
            "the old straight recovery chord must reproduce the guardian re-entry"
        );

        let route_clearance = crate::level1_mission::PROJECTILE_ACQUISITION_RANGE + 512;
        let (waypoints, _, _) = level_three_source_route_to_sites_for_test(
            &session,
            origin,
            vec![castle],
            &guardian_spawns,
            route_clearance,
        )
        .expect("the production movement resolver retains a guardian-safe recovery route");
        let threatened_waypoint = waypoints
            .iter()
            .min_by_key(|waypoint| {
                let dx = i32::from(waypoint.x.wrapping_sub(guardian_spawns[0].x).cast_signed());
                let dy = i32::from(waypoint.y.wrapping_sub(guardian_spawns[0].y).cast_signed());
                dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy))
            })
            .copied()
            .unwrap();
        let mut moved_roots = guardian_spawns.clone();
        for _ in 0..level_three_dragon_retreat_bound(0) {
            if !level_three_position_outside_dragon_clearance_for_test(
                threatened_waypoint,
                &moved_roots,
                route_clearance,
            ) {
                break;
            }
            let heading = i16::try_from(crate::heading_for_positions(
                moved_roots[0],
                threatened_waypoint,
            ))
            .unwrap();
            crate::move_entity(&mut moved_roots[0], heading, 0, 30);
        }
        assert!(
            !level_three_position_outside_dragon_clearance_for_test(
                threatened_waypoint,
                &moved_roots,
                route_clearance,
            ),
            "a source-speed moving root must invalidate the stale recovery route"
        );
        let (replanned, _, _) = level_three_source_route_to_sites_for_test(
            &session,
            origin,
            vec![castle],
            &moved_roots,
            route_clearance,
        )
        .expect("current root positions retain a replanned recovery route");
        assert!(replanned.iter().all(|waypoint| {
            level_three_position_outside_dragon_clearance_for_test(
                *waypoint,
                &moved_roots,
                route_clearance,
            )
        }));
        let mut cursor = origin;
        for waypoint in waypoints {
            let heading = i16::try_from(crate::heading_for_positions(cursor, waypoint)).unwrap();
            while {
                let dx = i32::from(waypoint.x.wrapping_sub(cursor.x).cast_signed());
                let dy = i32::from(waypoint.y.wrapping_sub(cursor.y).cast_signed());
                crate::legacy_sqrt(
                    dx.wrapping_mul(dx)
                        .wrapping_add(dy.wrapping_mul(dy))
                        .cast_unsigned(),
                ) > 256
            } {
                crate::move_entity(&mut cursor, heading, 0, 256);
                assert!(
                    level_three_position_outside_dragon_range_for_test(cursor, &guardian_spawns,),
                    "every selected recovery segment must remain outside guardian acquisition"
                );
            }
            cursor = waypoint;
        }
        assert_eq!((cursor.x, cursor.y), (castle.x, castle.y));
    }

    #[test]
    fn campaign_backend_public_castle_build_and_heal_reach_connected_site_after_skeletons() {
        let root = level_three_descriptor_fixture_path();
        let catalog = default_catalog().unwrap();
        let definition = Arc::new(load_mc2_campaign(&root, &catalog).unwrap());
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            66,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .apply_carried_spell_families(&[0, 2], Some(0))
            .unwrap();
        let castle_holder = session
            .backend()
            .campaign
            .level2_compatibility()
            .shared_spells()
            .local_player()
            .enabled_spell_holders[2];
        assert_ne!(castle_holder, 0);

        drive_real_level_three_skeleton_horde_to_guardian_dragons_for_test(&mut session);
        assert!(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .castle()
                .is_none()
        );
        let castle = build_real_level_three_carried_castle_for_test(&mut session);
        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(compatibility.economy().player_castle_entity_index(), castle);
        assert_eq!(
            compatibility
                .shared_spells()
                .local_player()
                .enabled_spell_holders[2],
            castle_holder
        );
        let max_life = compatibility.shared_spells().player_entity().max_life;
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .activate_authored_group_prerequisite_for_test(1)
            .unwrap();
        assert_eq!(level_three_dragon_fireball_targets(&session).len(), 34);
        let mut saw_damage = false;
        for _ in 0..4 {
            if matches!(
                fire_real_player_fireball_at_level_three_dragon_for_test(&mut session, None),
                DragonFireballCastOutcome::Damage(_)
            ) {
                saw_damage = true;
                break;
            }
        }
        assert!(
            saw_damage,
            "a public Dragon exchange must exercise Castle healing"
        );
        let fireball_holder = session
            .backend()
            .campaign
            .level2_compatibility()
            .shared_spells()
            .local_player()
            .enabled_spell_holders[0];
        let mut chronology = Vec::new();
        recover_at_real_level_three_castle_for_test(
            &mut session,
            fireball_holder,
            &mut chronology,
            0,
        );
        let compatibility = session.backend().campaign.level2_compatibility();
        let player = compatibility.shared_spells().player_entity();
        assert_eq!(player.life, max_life);
        assert_eq!(
            compatibility
                .shared_spells()
                .local_player()
                .enabled_spell_holders[2],
            castle_holder
        );
    }

    fn activate_and_retire_real_level_three_group_five_archers_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
    ) {
        const GROUP_FIVE_ROWS: &[u16] = &[
            166, 167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 180, 181, 182,
            183, 184, 185, 186, 187, 188, 189, 190, 191, 192, 193, 194,
        ];
        session
            .step(guard(session), GameCommand::default())
            .unwrap();
        let compatibility = session.backend().campaign.level2_compatibility();
        assert!(compatibility.dispatch_events().iter().any(|event| matches!(
            event,
            crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                source_slot: 218,
                group: 5,
                authored_indices,
                ..
            } if authored_indices.as_ref() == GROUP_FIVE_ROWS
        )));
        let archers = compatibility
            .economy()
            .authored_class5()
            .iter()
            .filter(|source| (177..=194).contains(&source.authored_index))
            .copied()
            .collect::<Vec<_>>();
        assert_eq!(archers.len(), 18);
        super::l3_public_combat::retire_public_combat_for_test(
            session,
            super::l3_public_combat::CombatFamily::Archer,
        );
        assert!(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .authored_class5()
                .iter()
                .all(|source| !(177..=194).contains(&source.authored_index)),
            "all eighteen real group-5 Archers must finish ordinary death/reclaim"
        );
    }

    fn claim_real_neutral_mana_sphere_for_castle_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
    ) -> (u16, i32, usize) {
        let player_entity = session
            .backend()
            .campaign
            .level2_compatibility()
            .state
            .entity_index;
        let compatibility = session.backend().campaign.level2_compatibility();
        let local_player = &compatibility.shared_spells().players()[0];
        let fireball_holder = local_player.enabled_spell_holders[0];
        let carried_fireball = compatibility
            .shared_spells()
            .dynamic_pickups()
            .iter()
            .find(|holder| holder.index == fireball_holder);
        assert!(
            carried_fireball.is_some_and(|holder| {
                holder.active
                    && holder.class == 15
                    && holder.model == 0
                    && holder.source_spell_parent_entity_index() == player_entity
            }),
            "carried Fireball relation failed before mana claim: player_action_life={:?}, holder_slot={fireball_holder}, dynamic={carried_fireball:?}, raw={:?}",
            compatibility
                .entities()
                .get(usize::from(player_entity))
                .map(|player| (player.action, player.life, player.control_flags)),
            compatibility.entities().get(usize::from(fireball_holder))
        );
        let spell_state = session.backend().semantic_spell_state_for_test().unwrap();
        assert!(
            spell_state.0.contains(&SpellKind::Possession),
            "Possession carry disappeared before the first mana claim: semantic={spell_state:?}, player={:?}, dynamic={:?}",
            session
                .backend()
                .campaign
                .level2_compatibility()
                .shared_spells()
                .players()[0],
            session
                .backend()
                .campaign
                .level2_compatibility()
                .shared_spells()
                .dynamic_pickups()
        );
        let sphere_slot = (0..256)
            .find_map(|_| {
                let settled = session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .spheres()
                    .iter()
                    .find(|sphere| {
                        sphere.active
                            && !sphere.pending_delete
                            && sphere.owner_entity_index == 0
                            && sphere.player_entity_index == 0
                    })
                    .map(|sphere| sphere.source_entity_index);
                if settled.is_none() {
                    session
                        .step(guard(session), GameCommand::default())
                        .unwrap();
                }
                settled
            })
            .expect("one real death sphere must settle while still neutral");
        let (sphere_position, target_top, mana) = {
            let compatibility = session.backend().campaign.level2_compatibility();
            let sphere = compatibility
                .economy()
                .spheres()
                .iter()
                .find(|sphere| sphere.source_entity_index == sphere_slot)
                .expect("the selected neutral sphere remains live");
            (
                sphere.position,
                compatibility
                    .possession_guidance_target_top_for_test(sphere_slot)
                    .expect("the real sphere exposes its source guidance top"),
                sphere.mana,
            )
        };
        let event_count_before = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .events()
            .len();
        session
            .step(
                guard(session),
                GameCommand {
                    select_spell: Some(SemanticId::parse("spell.possession").unwrap()),
                    ..GameCommand::default()
                },
            )
            .unwrap();
        let state = session.backend().campaign.level2_compatibility().state;
        let mut cast_position = sphere_position;
        crate::move_entity(
            &mut cast_position,
            state.yaw.wrapping_add(1_024),
            0,
            crate::level1_mission::POSSESSION_PROJECTILE_SPEED,
        );
        let mut launch_position = cast_position;
        launch_position.z = launch_position.z.wrapping_add(state.entity_fov);
        let (launch_yaw, launch_pitch) =
            crate::level1_mission::projectile_guidance_angles(launch_position, target_top);
        let compatibility = session.backend_mut().campaign.level2_compatibility_mut();
        compatibility
            .set_level2_entity_position(player_entity, cast_position)
            .unwrap();
        compatibility.set_level2_player_aim_for_test(launch_yaw, launch_pitch);
        session
            .step(
                guard(session),
                GameCommand {
                    cast_selected: true,
                    ..GameCommand::default()
                },
            )
            .unwrap();
        for _ in 0..32 {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .spheres()
                .iter()
                .any(|sphere| {
                    sphere.source_entity_index == sphere_slot
                        && sphere.active
                        && !sphere.pending_delete
                        && sphere.owner_entity_index == player_entity
                })
            {
                break;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        assert_eq!(
            session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .spheres()
                .iter()
                .find(|sphere| sphere.source_entity_index == sphere_slot)
                .map(|sphere| sphere.owner_entity_index),
            Some(player_entity),
            "ordinary Possession must claim the selected real death sphere"
        );
        (sphere_slot, mana, event_count_before)
    }

    fn await_real_castle_sphere_deposit_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        sphere_slot: u16,
        mana_before: i32,
        sphere_mana: i32,
        event_count_before: usize,
    ) -> i32 {
        let (player_entity, castle_slot, castle_position) = {
            let compatibility = session.backend().campaign.level2_compatibility();
            let castle = compatibility
                .economy()
                .castle()
                .expect("the carried Castle remains live before deposit");
            (
                compatibility.state.entity_index,
                castle.source_entity_index,
                castle.position,
            )
        };
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .set_level2_entity_position(player_entity, castle_position)
            .unwrap();
        let minimum_mana = mana_before.saturating_add(sphere_mana);
        for _ in 0..2_048 {
            let economy = session.backend().campaign.level2_compatibility().economy();
            if economy
                .castle()
                .is_some_and(|castle| castle.mana >= minimum_mana)
            {
                break;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let economy = session.backend().campaign.level2_compatibility().economy();
        let deposited_mana = economy
            .castle()
            .map(|castle| castle.mana)
            .expect("the carried Castle remains live through deposit");
        assert!(
            deposited_mana >= minimum_mana,
            "the ordinary stage-one carrier must deposit at least claimed sphere {sphere_slot}: before={mana_before}, sphere={sphere_mana}, after={deposited_mana}"
        );
        let castle_deposit = economy.events()[event_count_before..]
            .iter()
            .filter_map(|event| match event {
                crate::native_world::Level2EconomyEvent::ManaSphereCollected {
                    carrier_id,
                    mana,
                    ..
                } if *carrier_id == u32::from(castle_slot) => Some(*mana),
                crate::native_world::Level2EconomyEvent::ManaCarrierArrived {
                    castle_id,
                    mana,
                    ..
                }
                | crate::native_world::Level2EconomyEvent::CastleDefenderArrived {
                    castle_id,
                    mana,
                    ..
                } if *castle_id == castle_slot => Some(*mana),
                _ => None,
            })
            .fold(0_i32, i32::saturating_add);
        assert!(
            castle_deposit >= sphere_mana,
            "the persistent root/carrier/defender deposit events must account for the claimed payload: sphere={sphere_slot}, claimed={sphere_mana}, deposited={castle_deposit}"
        );
        deposited_mana
    }

    fn upgrade_real_castle_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        expected_level: u8,
    ) {
        let (player_entity, castle_position) = {
            let compatibility = session.backend().campaign.level2_compatibility();
            (
                compatibility.state.entity_index,
                compatibility
                    .economy()
                    .castle()
                    .expect("the Castle remains live before its upgrade")
                    .position,
            )
        };
        session
            .backend_mut()
            .campaign
            .level2_compatibility_mut()
            .set_level2_entity_position(player_entity, castle_position)
            .unwrap();
        session
            .step(
                guard(session),
                GameCommand {
                    select_spell: Some(SemanticId::parse("spell.castle").unwrap()),
                    ..GameCommand::default()
                },
            )
            .unwrap();
        session
            .step(
                guard(session),
                GameCommand {
                    cast_selected: true,
                    ..GameCommand::default()
                },
            )
            .unwrap();
        for _ in 0..128 {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .castle()
                .is_some_and(|castle| castle.level == expected_level)
            {
                break;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let castle = session
            .backend()
            .campaign
            .level2_compatibility()
            .economy()
            .castle()
            .expect("the upgraded Castle remains live");
        assert_eq!(castle.level, expected_level);
        assert_eq!(
            castle.mana_capacity,
            match expected_level {
                2 => 18_000,
                3 => 38_800,
                _ => unreachable!("the focused route upgrades only through stage three"),
            }
        );
    }

    pub(crate) fn drive_real_level_three_carried_castle_to_revealed_way_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
    ) {
        drive_real_level_three_skeleton_horde_to_guardian_dragons_for_test(session);
        build_real_level_three_carried_castle_for_test(session);
        drive_real_level_three_guardian_dragons_to_reveal_entrance_for_test(session);
        activate_and_retire_real_level_three_group_five_archers_for_test(session);
        for expected_level in 1..=2 {
            for _ in 0..40 {
                let castle = session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .castle()
                    .expect("the carried Castle remains live");
                if castle.mana >= castle.mana_capacity {
                    break;
                }
                let mana_before = castle.mana;
                let (sphere_slot, sphere_mana, event_count_before) =
                    claim_real_neutral_mana_sphere_for_castle_for_test(session);
                await_real_castle_sphere_deposit_for_test(
                    session,
                    sphere_slot,
                    mana_before,
                    sphere_mana,
                    event_count_before,
                );
            }
            upgrade_real_castle_for_test(session, expected_level + 1);
        }
        for _ in 0..40 {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .runtime()
                .objectives[0]
                .stage_selectors[2]
                == 2
            {
                break;
            }
            let mana_before = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .castle()
                .expect("the carried Castle remains live")
                .mana;
            let (sphere_slot, sphere_mana, event_count_before) =
                claim_real_neutral_mana_sphere_for_castle_for_test(session);
            await_real_castle_sphere_deposit_for_test(
                session,
                sphere_slot,
                mana_before,
                sphere_mana,
                event_count_before,
            );
        }
        for _ in 0..4 {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .runtime()
                .objectives[0]
                .stage_selectors[2]
                == 2
            {
                break;
            }
            session
                .step(guard(&session), GameCommand::default())
                .unwrap();
        }
        let compatibility = session.backend().campaign.level2_compatibility();
        let economy = compatibility.economy();
        let castle = economy.castle().expect("the carried Castle remains live");
        assert_eq!(castle.level, 3);
        assert!(castle.mana < castle.mana_capacity);
        assert_eq!(
            compatibility.runtime().objectives[0].stage_selectors[2],
            2,
            "the production Castle route must satisfy the exact 30% objective"
        );
    }

    pub(crate) fn drive_real_level_three_revealed_way_through_final_bees_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
    ) {
        const REVEALED_WAY_STAGE: usize = 3;
        const FINAL_BEE_STAGE: usize = 4;
        const BEE_ROWS: [u16; 6] = [149, 150, 152, 153, 154, 155];

        assert_eq!(
            &session
                .backend()
                .campaign
                .level2_compatibility()
                .runtime()
                .objectives[0]
                .stage_selectors[..5],
            &[2, 2, 2, 1, 1]
        );
        assert_eq!(
            session
                .snapshot()
                .value
                .objective_progress
                .current_objective
                .as_ref()
                .map(SemanticId::as_str),
            Some("objective.reach.revealed_way")
        );

        // The Castle-mana predicate is serviced post-pass. Its imported
        // model-32 gate can see selector 2 only on a following numeric pass,
        // where it constructs and visits the package's row-146 close command.
        let mut saw_group_two = false;
        for _ in 0..4 {
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
            saw_group_two |= session
                .backend()
                .campaign
                .level2_compatibility()
                .dispatch_events()
                .iter()
                .any(|event| {
                    matches!(
                        event,
                        crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                            source_slot: 128,
                            group: 2,
                            authored_indices,
                            ..
                        } if authored_indices.as_ref() == [146]
                    )
                });
            if saw_group_two {
                break;
            }
        }
        assert!(
            saw_group_two,
            "the following source pass must construct exact terrain-strip row 146"
        );

        let target = {
            let compatibility = session.backend().campaign.level2_compatibility();
            let stage = &compatibility.runtime().stages[REVEALED_WAY_STAGE];
            crate::Position {
                x: stage.axis_x.cast_unsigned(),
                y: stage.axis_y.cast_unsigned(),
                z: compatibility.state.position.z,
            }
        };
        for _ in 0..1_280 {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .runtime()
                .objectives[0]
                .stage_selectors[REVEALED_WAY_STAGE]
                == 2
            {
                break;
            }
            let state = session.backend().campaign.level2_compatibility().state;
            let desired = i16::try_from(crate::heading_for_positions(state.position, target))
                .expect("source heading is 11-bit");
            let correction = crate::turn_toward(state.yaw, desired, 127);
            session
                .step(
                    guard(session),
                    GameCommand {
                        longitudinal: LongitudinalControl::Accelerate,
                        roll_axis: correction.clamp(-24, 24) as i8,
                        pitch_axis: -127,
                        ..GameCommand::default()
                    },
                )
                .unwrap();
        }
        let compatibility = session.backend().campaign.level2_compatibility();
        assert_eq!(
            compatibility.runtime().objectives[0].stage_selectors[REVEALED_WAY_STAGE],
            2,
            "ordinary commanded flight did not reach the package point: state={:?}, target={target:?}",
            compatibility.state
        );
        assert_eq!(
            session
                .snapshot()
                .value
                .objective_progress
                .current_objective
                .as_ref()
                .map(SemanticId::as_str),
            Some("objective.clear.final_bees")
        );

        for _ in 0..4 {
            let bee_rows = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| bee.authored_index())
                .collect::<Vec<_>>();
            if bee_rows == BEE_ROWS {
                break;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let compatibility = session.backend().campaign.level2_compatibility();
        assert!(compatibility.dispatch_events().iter().any(|event| matches!(
            event,
            crate::native_world::Level2DispatchEvent::AuthoredGroupActivated {
                source_slot: 129,
                group: 3,
                authored_indices,
                ..
            } if authored_indices.as_ref() == BEE_ROWS
        )));
        assert_eq!(
            compatibility
                .economy()
                .bee_creatures()
                .iter()
                .filter_map(|bee| bee.authored_index())
                .collect::<Vec<_>>(),
            BEE_ROWS
        );
        assert_eq!(
            compatibility.runtime().objectives[0].stage_selectors[FINAL_BEE_STAGE],
            1
        );

        let first_life = compatibility
            .economy()
            .bee_creatures()
            .iter()
            .find(|bee| bee.authored_index() == Some(BEE_ROWS[0]))
            .expect("the first final Bee is live")
            .life;
        let first_hit = fire_real_player_fireball_at_bee_for_test(session, BEE_ROWS[0]);
        assert_eq!(first_hit.life, first_life.wrapping_sub(250));

        let retreat = {
            let first = session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .find(|bee| bee.authored_index() == Some(BEE_ROWS[0]))
                .expect("the first final Bee remains after its public hit");
            crate::Position {
                x: first.position.x.wrapping_add(20_000),
                y: first.position.y.wrapping_add(20_000),
                z: first.position.z,
            }
        };
        position_player_at_bee_fireball_boundary_for_test(session, retreat);

        let attacker = session
            .backend()
            .campaign
            .level2_compatibility()
            .state
            .entity_index;
        let mut terminal_rows = BTreeSet::new();
        let mut reclaimed_rows = BTreeSet::new();
        for authored_index in BEE_ROWS {
            for _ in 0..16 {
                let Some(bee) = session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .bee_creatures()
                    .iter()
                    .find(|bee| bee.authored_index() == Some(authored_index))
                    .copied()
                else {
                    break;
                };
                if bee.life < 0 {
                    terminal_rows.insert(authored_index);
                    break;
                }
                assert!(
                    session
                        .backend_mut()
                        .campaign
                        .level2_compatibility_mut()
                        .economy_mut()
                        .stage_bee_mailbox_damage_for_test(bee.source_entity_index, attacker, 250,)
                );
                let life_before = bee.life;
                let mut consumed = false;
                for _ in 0..4 {
                    session
                        .step(guard(session), GameCommand::default())
                        .unwrap();
                    let current = session
                        .backend()
                        .campaign
                        .level2_compatibility()
                        .economy()
                        .bee_creatures()
                        .iter()
                        .find(|candidate| candidate.authored_index() == Some(authored_index))
                        .copied()
                        .expect("the source-arrived pulse is consumed before Bee reclaim");
                    if current.life == life_before.wrapping_sub(250) {
                        consumed = true;
                        if current.life < 0 {
                            assert_eq!(current.action, 20);
                            terminal_rows.insert(authored_index);
                        }
                        break;
                    }
                }
                assert!(
                    consumed,
                    "Bee {authored_index} did not consume its source mailbox"
                );
                if terminal_rows.contains(&authored_index) {
                    break;
                }
            }

            for _ in 0..24 {
                if session
                    .backend()
                    .campaign
                    .level2_compatibility()
                    .economy()
                    .bee_creatures()
                    .iter()
                    .all(|bee| bee.authored_index() != Some(authored_index))
                {
                    reclaimed_rows.insert(authored_index);
                    break;
                }
                session
                    .step(guard(session), GameCommand::default())
                    .unwrap();
            }
        }

        assert_eq!(terminal_rows, BTreeSet::from(BEE_ROWS));
        for _ in 0..24 {
            if session
                .backend()
                .campaign
                .level2_compatibility()
                .economy()
                .bee_creatures()
                .iter()
                .all(|bee| !BEE_ROWS.contains(&bee.authored_index().unwrap_or(u16::MAX)))
            {
                break;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        let compatibility = session.backend().campaign.level2_compatibility();
        let remaining = compatibility
            .economy()
            .bee_creatures()
            .iter()
            .filter_map(|bee| bee.authored_index())
            .filter(|row| BEE_ROWS.contains(row))
            .collect::<Vec<_>>();
        assert!(
            remaining.is_empty(),
            "final Bees were not reclaimed: {remaining:?}"
        );
        assert!(
            BTreeSet::from([149, 150, 152, 153, 154]).is_subset(&reclaimed_rows),
            "the first five final Bees must each reach following-pass reclaim: {reclaimed_rows:?}"
        );
        assert_eq!(
            compatibility.runtime().objectives[0].stage_selectors[FINAL_BEE_STAGE],
            2
        );
        assert_eq!(compatibility.runtime().objectives[0].is_level_end, 1);
    }

